def regexr_transform(column):
    if column == 'flight':
        return_value = ''
        for value in column:
            cleaned_value = re.sub(r'[A-Z]{2}-[0-9]{3}-[A-Z]{3}', r'\g<1>\g<2>', value) # remove - and standardize format to AAA-XXX
            return_value += cleaned_value + ' '
        return return_value.strip() # remove extra spaces at the end
